var authRouter = express.Router();
authRouter.post("/register", async (req, res) => {
  const {
    email,
    password,
    name,
    phone,
    dateOfBirth,
    ageConfirmed,
    notProhibited,
    legallyEligible,
    agreedToTerms
  } = req.body || {};
  if (!ageConfirmed || !notProhibited || !legallyEligible) {
    return res.status(400).json({
      error: "attestation_required",
      message: "You must attest that you are of legal age, not a prohibited person, and legally eligible to purchase and possess."
    });
  }
  if (!agreedToTerms) {
    return res.status(400).json({
      error: "terms_required",
      message: "You must agree to the Terms & Conditions and Privacy Policy to register."
    });
  }
  if (!password || String(password).length < 8) {
    return res.status(400).json({ error: "weak_password", message: "Password must be at least 8 characters." });
  }
  const result = store.createBidder({
    email,
    password,
    name,
    phone,
    dateOfBirth,
    agreedToTerms: true,
    attestation: { ageConfirmed: true, notProhibited: true, legallyEligible: true, at: Date.now() }
  });
  if (!result.ok) {
    const msg = result.error === "email_taken" ? "An account with that email already exists." : "Missing required fields.";
    return res.status(400).json({ error: result.error, message: msg });
  }
  try {
    await sendEmail(verificationEmail(result.user, result.verifyToken));
  } catch (e) {
    console.error("[auth] verification email failed:", e.message);
  }
  res.json({ ok: true, message: "Check your email to verify your address. Staff will approve your account before you can bid." });
});
authRouter.post("/login", (req, res) => {
  const { email, password } = req.body || {};
  const user = store.authenticate(email, password);
  if (!user) return res.status(401).json({ error: "bad_credentials", message: "Incorrect email or password." });
  setSession(res, user.id);
  res.json({ ok: true, user: store.publicUser(user) });
});
authRouter.post("/logout", (req, res) => {
  const raw = req.cookies?.[COOKIE];
  const sid = raw ? unsign(raw, config.sessionSecret) : null;
  if (sid) store.destroySession(sid);
  res.clearCookie(COOKIE);
  res.json({ ok: true });
});
authRouter.get("/me", (req, res) => {
  if (!req.user) return res.json({ user: null });
  const u = store.publicUser(req.user);
  res.json({ user: {
    id: u.id,
    email: u.email,
    name: u.name,
    role: u.role,
    status: u.status,
    emailVerified: u.emailVerified,
    biddingLimit: u.biddingLimit
  } });
});

